 static function resource(string $entity):array{$def=self::definitions()[$entity]??null;if(!$def)fail('Unknown resource.',404);return $def;}
 static function save(string $entity,array $d):int {
  $def=self::resource($entity);$id=(int)($d['id']??0);staff($id?'edit':'create');if($def['module'])module($def['module']);
  return tx(function()use($entity,$d,$def,$id){$values=[];foreach($def['fields'] as $field=>$type){if(!array_key_exists($field,$d))continue;$v=$d[$field];if(is_array($type)){if(!in_array($v,$type,true))fail('Invalid '.$field);}elseif($type==='check')$v=(int)(bool)$v;elseif($type==='json'){$v=is_array($v)?json_encode($v):$v;if(!is_array(json_decode($v,true)))fail('Enter a JSON array.');}elseif($type==='number')$v=$v===''?null:integer($v,0);elseif(in_array($type,['categories','brands','attributes','products'],true))$v=$v===''?null:integer($v,1);elseif($type==='image')self::imagePath((string)$v);elseif($type==='date'&&$v!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v))fail('Invalid date.');elseif(!is_string($v)||strlen($v)>20000)fail('Invalid field.');$values[$field]=$v;}
   if($entity==='categories'){q('SELECT id FROM categories ORDER BY id FOR UPDATE');$parent=$values['parent_id']??null;if($id&&$parent&&in_array((int)$parent,Catalog::descendants($id),true))fail('A category cannot be its own descendant.');}
   if(isset($values['slug'])&&!preg_match('/^[a-z0-9][a-z0-9-]{0,180}$/D',$values['slug']))fail('Use a lowercase URL slug.');
   if(isset($values['name'])&&trim($values['name'])==='')fail('Name is required.');
   if($entity==='coupons'){if(($values['type']??'')==='percentage'&&($values['value']??0)>10000)fail('Percentage is in basis points, 0–10000.');if(($values['ends_at']??'')<($values['starts_at']??''))fail('End date must follow start date.');$values['code']=strtoupper(trim($values['code']??''));}
   foreach(['primary_url','secondary_url','link'] as $f)if(isset($values[$f])&&safeLink($values[$f])==='#')fail('Use a relative path or HTTP(S) URL.');
   if(!$values)fail('No fields supplied.');if($id){if(!one("SELECT id FROM $entity WHERE id=?",[$id]))fail('Record not found.',404);$set=implode(',',array_map(fn($x)=>"`$x`=?",array_keys($values)));q("UPDATE $entity SET $set WHERE id=?",[...array_values($values),$id]);}else{if($entity==='reviews')fail('Reviews must be submitted by customers.');$columns=implode(',',array_keys($values));$marks=implode(',',array_fill(0,count($values),'?'));q("INSERT INTO $entity($columns) VALUES($marks)",array_values($values));$id=(int)db()->lastInsertId();}audit('save',$entity,$id);return $id;});
 }
 static function imagePath(string $v):void {if($v!==''&&!preg_match('~^(assets|uploads)/[a-zA-Z0-9_./-]+\.(webp|png|jpg|jpeg|gif|svg)$~D',$v))fail('Use an uploaded image path.');if(str_contains($v,'..')||str_contains($v,':'))fail('Invalid image path.');}
 static function product(array $d):int {
  $id=(int)($d['id']??0);staff($id?'edit':'create');return tx(function()use($d,$id){foreach(['name','slug','sku','category_id'] as $f)if(empty(trim((string)($d[$f]??''))))fail('Complete product details.',422,[$f=>'Required']);if(!preg_match('/^[a-z0-9][a-z0-9-]{0,180}$/D',$d['slug']))fail('Invalid slug.');if(!in_array($d['status']??'draft',['draft','active','archived'],true))fail('Invalid status.');if(!in_array($d['condition_type']??'new',['new','used'],true))fail('Invalid condition.');if(($d['condition_type']??'new')==='used')module('used');
   $prior=$id?one('SELECT brand_id,supplier_id FROM products WHERE id=?',[$id]):[];$fields=['name','slug','sku','barcode','category_id','brand_id','supplier_id','short_description','description','unit','condition_type','status','featured','new_arrival','deal','has_variants','warranty','tags','seo_title','seo_description'];$values=[];foreach($fields as $f){$values[$f]=$d[$f]??(in_array($f,['featured','new_arrival','deal','has_variants'],true)?0:'');if($f==='brand_id'&&!enabled('brands'))$values[$f]=$prior['brand_id']??null;if($f==='supplier_id'&&!enabled('suppliers'))$values[$f]=$prior['supplier_id']??null;if(in_array($f,['brand_id','supplier_id'],true)&&!$values[$f])$values[$f]=null;}
   if($id){$existing=one('SELECT * FROM products WHERE id=? FOR UPDATE',[$id]);if(!$existing)fail('Product not found.',404);q('UPDATE products SET '.implode(',',array_map(fn($k)=>"$k=?",$fields)).' WHERE id=?',[...array_values($values),$id]);}else{q('INSERT INTO products('.implode(',',$fields).') VALUES('.implode(',',array_fill(0,count($fields),'?')).')',array_values($values));$id=(int)db()->lastInsertId();}
   $assigned=all('SELECT a.* FROM attributes a JOIN category_attributes ca ON ca.attribute_id=a.id WHERE ca.category_id=?',[$d['category_id']]);$attrs=$d['attributes']??[];
   foreach($assigned as $a){$value=$attrs[$a['id']]??'';if($a['required']&&($value===''||$value===[]))fail('Required attribute: '.$a['name']);if($value===''||$value===[])continue;self::attributeValue($a,$value);q('INSERT INTO product_attribute_values(product_id,attribute_id,value) VALUES(?,?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$id,$a['id'],is_array($value)?json_encode($value):(string)$value]);}
   foreach(all('SELECT attribute_id FROM product_attribute_values WHERE product_id=?',[$id]) as $old)if(!array_key_exists($old['attribute_id'],$attrs)||$attrs[$old['attribute_id']]==='')q('DELETE FROM product_attribute_values WHERE product_id=? AND attribute_id=?',[$id,$old['attribute_id']]);
   $variants=$d['variants']??[];if(!$variants)fail('Add at least one sellable option.');if(empty($d['has_variants'])&&count($variants)!==1)fail('Simple products need exactly one sellable option.');$keep=[];$combos=[];
   foreach($variants as $v){$vid=(int)($v['id']??0);$old=$vid?one('SELECT * FROM product_variants WHERE id=? AND product_id=? FOR UPDATE',[$vid,$id]):null;if($vid&&!$old)fail('Variant belongs to another product.');$price=cents($v['price']);$sale=isset($v['sale_price'])&&$v['sale_price']!==''?cents($v['sale_price']):null;if($sale!==null&&$sale>$price)fail('Sale price exceeds regular price.');$cost=allowed('costs')?cents($v['cost']??'0'):(int)($old['cost']??0);$dt=$v['deposit_type']??'none';if(!in_array($dt,['none','fixed','percentage'],true))fail('Invalid deposit rule.');$dv=$dt==='none'?0:cents($v['deposit_value']??'0');if(($dt==='percentage'&&$dv>10000)||($dt==='fixed'&&$dv>($sale??$price)))fail('Deposit exceeds permitted amount.');$availability=$v['availability']??'normal';if(!in_array($availability,['normal','preorder'],true))fail('Invalid availability.');if($availability==='preorder')module('preorders');if($dt!=='none')module('advances');self::imagePath($v['image']??'');$opts=$v['options']??[];ksort($opts,SORT_NUMERIC);$combo=json_encode($opts);if(in_array($combo,$combos,true))fail('Duplicate variant combination.');$combos[]=$combo;$labels=[];foreach($opts as $aid=>$oid){$opt=one('SELECT o.label,a.name FROM attribute_options o JOIN attributes a ON a.id=o.attribute_id JOIN category_attributes ca ON ca.attribute_id=a.id WHERE o.id=? AND a.id=? AND a.variant=1 AND ca.category_id=?',[$oid,$aid,$d['category_id']]);if(!$opt)fail('Invalid variant attribute option.');$labels[]=$opt['name'].': '.$opt['label'];}if(!empty($d['has_variants'])&&!$opts)fail('Variant products need attribute options.');$label=$labels?implode(' / ',$labels):'Standard';$sku=trim($v['sku']??'');if(!$sku)fail('Variant SKU is required.');$expected=($v['expected_date']??'')?:null;if($expected&&!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$expected))fail('Invalid expected date.');
    $vs=['product_id'=>$id,'sku'=>$sku,'barcode'=>$v['barcode']??'','label'=>$label,'combination'=>$combo,'price'=>$price,'sale_price'=>$sale,'cost'=>$cost,'image'=>$v['image']??'','enabled'=>(int)($v['enabled']??1),'track_stock'=>(int)($v['track_stock']??1),'low_stock'=>integer($v['low_stock']??3),'availability'=>$availability,'expected_date'=>$expected,'max_preorder'=>($v['max_preorder']??'')===''?null:integer($v['max_preorder'],1),'deposit_type'=>$dt,'deposit_value'=>$dv];
    if($vid)q('UPDATE product_variants SET '.implode(',',array_map(fn($k)=>"$k=?",array_keys($vs))).' WHERE id=?',[...array_values($vs),$vid]);else{q('INSERT INTO product_variants('.implode(',',array_keys($vs)).') VALUES('.implode(',',array_fill(0,count($vs),'?')).')',array_values($vs));$vid=(int)db()->lastInsertId();q('INSERT INTO inventory_balances(variant_id,physical) VALUES(?,?)',[$vid,integer($v['stock']??0)]);if((int)($v['stock']??0)>0)Commerce::movement($vid,(int)$v['stock'],'initial',null,'Initial stock');}q('DELETE FROM variant_attribute_values WHERE variant_id=?',[$vid]);foreach($opts as $aid=>$oid)q('INSERT INTO variant_attribute_values(variant_id,attribute_id,option_id) VALUES(?,?,?)',[$vid,$aid,$oid]);$keep[]=$vid;
   }
   q('UPDATE product_variants SET enabled=0 WHERE product_id=? AND id NOT IN ('.implode(',',array_fill(0,count($keep),'?')).')',[$id,...$keep]);if(isset($d['images'])){q('DELETE FROM product_images WHERE product_id=?',[$id]);foreach($d['images'] as $i=>$im){self::imagePath($im['path']);q('INSERT INTO product_images(product_id,path,alt,sort_order) VALUES(?,?,?,?)',[$id,$im['path'],$im['alt']??$d['name'],$i]);}}audit('product.save','product',$id);return $id;
  });
 }
 static function attributeValue(array $a,mixed $v):void{switch($a['type']){case 'number':if(!is_numeric($v))fail('Invalid number: '.$a['name']);break;case 'boolean':if(!in_array((string)$v,['0','1'],true))fail('Invalid boolean.');break;case 'date':if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',(string)$v))fail('Invalid date.');break;case 'dropdown':case 'color':case 'multi-select':$list=is_array($v)?$v:[$v];foreach($list as $option)if(!one('SELECT id FROM attribute_options WHERE attribute_id=? AND label=?',[$a['id'],$option]))fail('Invalid option for '.$a['name']);break;default:if(!is_string($v)||mb_strlen($v)>3000)fail('Invalid text.');}}
 static function assignments(array $d):void{staff('edit');tx(function()use($d){$id=integer($d['category_id'],1);q('DELETE FROM category_attributes WHERE category_id=?',[$id]);foreach(array_unique($d['attributes']??[]) as $aid)q('INSERT INTO category_attributes VALUES(?,?)',[$id,integer($aid,1)]);audit('attributes.assign','category',$id);});}
 static function settings(array $d):void{staff('settings');$keys=['store_name','legal_name','tagline','address','phone','email','logo','currency','currency_symbol','timezone','top_message','footer_text','bank_details','invoice_note','site_origin','tax_basis_points','reservation_minutes','delivery_zones','free_shipping_threshold','social_links'];$modules=['inventory','preorders','advances','wishlist','reviews','brands','suppliers','coupons','delivery','online','accounts','used','warranty','purchases'];tx(function()use($d,$keys,$modules){q("SELECT name FROM settings WHERE name='currency' FOR UPDATE");if(isset($d['currency'])&&$d['currency']!==setting('currency')&&one("SELECT id FROM orders WHERE status NOT IN ('completed','cancelled') LIMIT 1"))fail('Settle open orders before changing currency.');if(isset($d['currency'])&&!preg_match('/^[A-Z]{3}$/D',$d['currency']))fail('Use a three-letter currency code.');if(isset($d['timezone'])&&!in_array($d['timezone'],DateTimeZone::listIdentifiers(),true))fail('Invalid timezone.');foreach(['delivery_zones','social_links'] as $k)if(isset($d[$k])&&is_string($d[$k])){$d[$k]=json_decode($d[$k],true);if(!is_array($d[$k]))fail('Invalid JSON object: '.$k);}foreach($d['delivery_zones']??[] as $v)integer($v,0);if(isset($d['tax_basis_points']))integer($d['tax_basis_points'],0,10000);if(!empty($d['module_online']))fail('Online payments require a real configured gateway.');$inventory=(bool)($d['module_inventory']??enabled('inventory'));$purchases=(bool)($d['module_purchases']??enabled('purchases'));$suppliers=(bool)($d['module_suppliers']??enabled('suppliers'));$preorders=(bool)($d['module_preorders']??enabled('preorders'));$advances=(bool)($d['module_advances']??enabled('advances'));if($purchases&&(!$inventory||!$suppliers))fail('Purchases require inventory and suppliers.');if($advances&&!$preorders)fail('Advances require pre-orders.');if(!$inventory&&one("SELECT id FROM inventory_reservations WHERE state='reserved' LIMIT 1"))fail('Resolve active stock reservations before disabling inventory.');if(isset($d['logo']))self::imagePath($d['logo']);foreach($modules as $m)$keys[]='module_'.$m;foreach($keys as $k)if(array_key_exists($k,$d))q('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$k,json_encode($d[$k])]);audit('settings.save','settings',0);});}
 static function upload(array $f,bool $private=false):string{if(($f['error']??1)!==UPLOAD_ERR_OK||($f['size']??0)>5*1024*1024)fail('Upload a JPG, PNG, or WebP image under 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))fail('Unsupported image format.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp'],true))fail('Invalid extension.');$size=getimagesize($f['tmp_name']);if(!$size||$size[0]>8000||$size[1]>8000||$size[0]*$size[1]>30000000)fail('Image dimensions exceed the limit.');$image=imagecreatefromstring(file_get_contents($f['tmp_name']));if(!$image)fail('Cannot decode image.');$max=$private?2000:1400;if(max(imagesx($image),imagesy($image))>$max)$image=imagescale($image,(int)round(imagesx($image)*$max/max(imagesx($image),imagesy($image))));$name=bin2hex(random_bytes(16)).'.webp';$path=($private?'storage/private/':'public/uploads/').$name;imagewebp($image,ROOT.'/'.$path,85);if(!$private){$thumb=imagescale($image,min(360,imagesx($image)));imagewebp($thumb,ROOT.'/public/uploads/'.substr($name,0,-5).'-thumb.webp',82);imagedestroy($thumb);}imagedestroy($image);return $private?$name:'uploads/'.$name;}
 static function purchase(array $d):int{module('purchases');staff('create');return tx(function()use($d){q('INSERT INTO purchase_receipts(supplier_id,reference,notes) VALUES(?,?,?)',[integer($d['supplier_id'],1),$d['reference']??'',$d['notes']??'']);$id=(int)db()->lastInsertId();if(empty($d['items']))fail('Add purchase lines.');foreach($d['items'] as $i)q('INSERT INTO purchase_receipt_items(purchase_id,variant_id,quantity,unit_cost) VALUES(?,?,?,?)',[$id,integer($i['variant_id'],1),integer($i['quantity'],1),cents($i['unit_cost'])]);audit('purchase.create','purchase',$id);return $id;});}
 static function staffSave(array $d):int{staff('staff');$id=(int)($d['id']??0);if(!filter_var($d['email']??'',FILTER_VALIDATE_EMAIL)||!trim($d['name']??''))fail('Name and valid email required.');if(!in_array($d['role']??'',['Super Admin','Admin','Sales Staff'],true))fail('Invalid role.');return tx(function()use($d,$id){$supers=all("SELECT id FROM staff_users WHERE role='Super Admin' AND enabled=1 FOR UPDATE");$old=$id?one('SELECT * FROM staff_users WHERE id=?',[$id]):null;if($old&&$old['role']==='Super Admin'&&count($supers)<=1&&($d['role']!=='Super Admin'||empty($d['enabled'])))fail('Keep at least one active Super Admin.');$perms=array_values(array_intersect($d['permissions']??[],self::permissions()));$v=[$d['name'],strtolower($d['email']),$d['role'],json_encode($perms),(int)(bool)($d['enabled']??1)];if($id){q('UPDATE staff_users SET name=?,email=?,role=?,permissions=?,enabled=? WHERE id=?',[...$v,$id]);if(!empty($d['password'])){Auth::password($d['password']);q('UPDATE staff_users SET password=? WHERE id=?',[password_hash($d['password'],PASSWORD_DEFAULT),$id]);}}else{Auth::password($d['password']??'');q('INSERT INTO staff_users(name,email,role,permissions,enabled,password) VALUES(?,?,?,?,?,?)',[...$v,password_hash($d['password'],PASSWORD_DEFAULT)]);$id=(int)db()->lastInsertId();}audit('staff.save','staff',$id);return $id;});}
 static function permissions():array{return ['view','create','edit','archive','export','orders.view','orders.edit','inventory','payments.record','payments.verify','refunds','costs','settings','staff','reports','customers','audit'];}
